package shortcut

import (
	"fmt"
	"strings"

	"github.com/MohamedBasaleh/kpod/internal/config"
)

const fileHeader = `# Generated by kpod.
# Do not edit manually; use ` + "`kpod shortcut`" + `.
`

func Render(cfg config.Config, shell string) (string, error) {
	_ = shell
	var b strings.Builder
	b.WriteString(fileHeader)
	b.WriteByte('\n')
	ids := SortedIDs(cfg)
	if len(ids) == 0 {
		b.WriteString("# No shortcuts configured.\n")
		return b.String(), nil
	}
	for _, id := range ids {
		sc := cfg.Shortcuts[id]
		if err := ValidateID(id); err != nil {
			return "", err
		}
		act, err := CanonicalAction(sc.Action)
		if err != nil {
			return "", fmt.Errorf("k-%s: %w", id, err)
		}
		name := CommandName(id)
		fmt.Fprintf(&b, "%s() {\n  command kpod %s %s \"$@\"\n}\n\n", name, shellQuote(sc.Environment), shellQuote(string(act)))
	}
	return b.String(), nil
}

func WriteAliasFiles(paths config.Paths, cfg config.Config) error {
	body, err := Render(cfg, "zsh")
	if err != nil {
		return err
	}
	if err := writeFile(paths.AliasFile("zsh"), []byte(body)); err != nil {
		return err
	}
	bash, err := Render(cfg, "bash")
	if err != nil {
		return err
	}
	return writeFile(paths.AliasFile("bash"), []byte(bash))
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}
